const r = $input.first().json.value;
const jobs = r?.job;

if (Array.isArray(jobs) && jobs.length !== 1) {
  throw Error('Se esperaba exactamente un trabajo');
}

const job = Array.isArray(jobs) ? jobs[0] : jobs;

if (
  r?.ok !== true ||
  !job ||
  ['id', 'engine', 'lease_token'].some(
    k => typeof job[k] !== 'string' || !job[k].trim()
  )
) {
  throw Error('El CRM no entregó un trabajo válido');
}

return [{ json: { ...job } }];

