function approvedLocationReply(value){const q=String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[¿?!.]/g,'').trim().replace(/\s+/g,' ');return /^(?:hola[, ]+)?(?:donde (?:queda|esta|se ubica|se encuentra) (?:el |la )?(?:proyecto|showroom|edificio|infinity(?: 224)?)|(?:cual es|me das|me compartes|me envias) (?:la )?(?:direccion|ubicacion)(?: del (?:proyecto|showroom|edificio))?)$/.test(q)?'Estamos en Calle La Apacheta 224, San Miguel. ¿Te gustaría coordinar una visita al showroom?':null;}
function buildReferences(drive,observations){const refs=[];const add=(id,tool,data,original)=>{if(typeof data==='string'&&data.length>=8&&data.length<=800&&original.includes(data))refs.push({id,tool,data});};(drive||[]).forEach((s,si)=>String(s.text||'').split('\n').forEach((line,li)=>add('drive:'+si+':'+li,'Carpeta_autorizada_GDrive',line,String(s.text||''))));(observations||[]).forEach((o,oi)=>{if(o.tool!=='Catalogo_comercial_Sheets')return;const text=typeof o.data==='string'?o.data:JSON.stringify(o.data);let rows;try{rows=JSON.parse(text);}catch{}if(Array.isArray(rows))rows.forEach((row,ri)=>add('catalog:'+oi+':'+ri,o.tool,JSON.stringify(row),text));else add('catalog:'+oi+':0',o.tool,text,text);});return refs;}
const j=$('Conservar trabajo').first().json;const input=$input.first().json;let context;try{context=$('Preparar contexto Lola').first().json;}catch{context={};}let memory;try{memory=$('Aplicar memoria a la conversación').first().json;}catch{memory={};}let agent;try{agent=$('Lola Comercial').first().json;}catch{agent={};}const observed=(agent.intermediateSteps||[]).filter(s=>s.observation!==undefined).map(s=>({tool:String(s.action?.tool||s.tool||''),data:typeof s.observation==='string'?s.observation:JSON.stringify(s.observation)}));const references=buildReferences(memory.drive_context?.sources||[],observed);let output=input.output;if(output&&typeof output==='object'&&Array.isArray(output.commercial_evidence))output={...output,commercial_evidence:output.commercial_evidence.map(e=>{const ref=references.find(r=>r.id===e.data&&r.tool===e.tool);return ref?{tool:ref.tool,data:ref.data}:e;})};const locationReply=approvedLocationReply(context.transcript||context.text||j.text);if(locationReply&&output&&typeof output==='object'&&!output.opt_out)output={reply:locationReply,profile:Object.fromEntries(['name','phone','email','interest','purchase_method','initial_payment'].map(k=>[k,context.profile?.[k]??null])),handoff:false,opt_out:false,commercial_answer:false,commercial_evidence:[]};return [{json:{engine:j.engine,action:'lola_job_complete',job_id:j.id,lease_token:j.lease_token,transcript:context.transcript||'',...(input.error||agent.error?{error:'generation_failed'}:{result:{output,observed_evidence:observed}})}}];

const task=$('Autorizar operación en CRM').first().json.value.task;const response=$input.first().json;
const status=Number(response.statusCode||(task.kind==='mail'&&response.id?200:0));
return [{json:{engine:$('Conservar trabajo').first().json.engine,action:'lola_task_complete',job_id:task.job_id,lease_token:task.lease_token,status,response,...(response.error?{error:'provider_error'}:{})}}];

const j=$input.first().json;
const HABILITAR_GEMINI=true; // Apoyo condicional; la memoria sigue en PostgreSQL.
const normal=String(j.text||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const red=v=>String(v||'').replace(/https?:\/\/\S+/gi,'[enlace]').replace(/[\w.+-]+@[\w.-]+\.[a-z]{2,}/gi,'[correo]').replace(/(?:\+?\d[\d ()-]{6,}\d)/g,'[numero]');
const direct=/\b(precio|precios|descuento|rebaja|asesor|humano|cancelar|reprogramar|no me escribas|darme de baja)\b/.test(normal);
const groups=[['preferences',/familia|dormitorio|ambiente|trabaj|mascota/],['concern',/preocupa|duda|confund|entiendo|insegur/],['comparison',/compar|diferencia|elegir|decidir|opciones/],['continuity',/antes|anterior|otro dia|record|retomar/]].filter(([,re])=>re.test(normal)).map(([tag])=>tag);
const consult=HABILITAR_GEMINI&&!direct&&!j.fixed_reply&&!j.kind&&normal.length>=100&&groups.length>=2;
const history=(j.history||[]).slice(-4).map(m=>({role:m.direction==='inbound'?'customer':'assistant',text:red(m.text).slice(0,180)}));
return [{json:{...j,claude_consult:consult,claude_context:consult?{current_message:red(j.text).slice(0,1200),recent_context:history}:null,claude_advice:null,claude_status:consult?'requested':HABILITAR_GEMINI?'not_needed':'disabled'}}];

const j=$('Evaluar apoyo condicional de Gemini').first().json;const r=$input.first().json;
let advice=null,status='unavailable';
try{if(r.error)throw Error('model_error');let raw=r.text??r.output??r.response;if(typeof raw!=='string'||raw.length>2000)throw Error('invalid');raw=raw.replace(/^```(?:json)?\s*|\s*```$/g,'');const a=JSON.parse(raw);
const intents=['preferences','concern','comparison','continuity'];
if(Object.keys(a).some(k=>!['intents','tone','strategy'].includes(k))||!Array.isArray(a.intents)||a.intents.length>4||a.intents.some(v=>!intents.includes(v))||!['warm','empathetic','concise'].includes(a.tone)||!['answer_then_question','clarify_ambiguity','summarize_next_step'].includes(a.strategy))throw Error('invalid');
advice={intents:[...new Set(a.intents)],tone:a.tone,strategy:a.strategy};status='accepted';}catch{}
return [{json:{...j,claude_advice:advice,claude_status:status,claude_context:null}}];
